diff --git a/lib/features/entries/domain/entities/pending_entry_write.dart b/lib/features/entries/domain/entities/pending_entry_write.dart
new file mode 100644
index 0000000..28ad25b
--- /dev/null
+++ b/lib/features/entries/domain/entities/pending_entry_write.dart
@@ -0,0 +1,126 @@
+import '../../../../core/failure/failure.dart';
+import 'entry.dart';
+
+/// A [PendingEntryWrite]'s own lifecycle — exactly the two states spec-4-2
+/// needs (Boundaries: "status = inFlight or failed(Failure)"). A write that
+/// resolves successfully is never represented here at all: `PendingEntry
+/// WriteTracker.create()`/`retry()` drop the record outright on success
+/// (Boundaries: "tracker drops the record") rather than modeling a third
+/// "confirmed" variant — nothing downstream ever needs to render a pending
+/// write as confirmed, only to stop rendering it as pending.
+sealed class PendingEntryWriteStatus {
+  const PendingEntryWriteStatus();
+}
+
+/// The write is in flight — `create()`/`retry()` already called the
+/// repository, no response yet.
+class PendingEntryWriteInFlight extends PendingEntryWriteStatus {
+  const PendingEntryWriteInFlight();
+
+  @override
+  bool operator ==(Object other) => other is PendingEntryWriteInFlight;
+
+  @override
+  int get hashCode => (PendingEntryWriteInFlight).hashCode;
+
+  @override
+  String toString() => 'PendingEntryWriteInFlight()';
+}
+
+/// The write's last attempt failed — [failure] is kept verbatim so a later
+/// retry can replay the exact same payload, and so `deriveSyncBadgeState()`
+/// can read [Failure.retryable] off it directly (Boundaries: "Tap on error
+/// badge: if `failure.retryable`...").
+class PendingEntryWriteFailed extends PendingEntryWriteStatus {
+  const PendingEntryWriteFailed({required this.failure});
+
+  final Failure failure;
+
+  @override
+  bool operator ==(Object other) =>
+      identical(this, other) ||
+      (other is PendingEntryWriteFailed && other.failure == failure);
+
+  @override
+  int get hashCode => failure.hashCode;
+
+  @override
+  String toString() => 'PendingEntryWriteFailed(failure: $failure)';
+}
+
+/// A capture write (`TextEntryCubit`/`AudioEntryCubit`/`PhotoEntryCubit`'s
+/// own `save()`) that `PendingEntryWriteTracker` is currently tracking —
+/// either still in flight or failed-but-not-yet-retried (Intent). [tempId]
+/// is a client-generated id (`PendingEntryWriteTrackerImpl`'s own
+/// generator), never the server's real `Entry.id` — it exists only so
+/// [PendingEntryWriteTracker.retry] and `MeusRegistrosCubit`'s own per-card
+/// lookup (`MeusRegistrosLoaded.badgeFor`) have something stable to key on
+/// while the write has no server-assigned id yet.
+///
+/// Plain hand-rolled equality (existing convention — mirrors [Entry]/
+/// [EntryDateGroup], never `freezed`, Tasks: "hand-rolled equality
+/// (existing convention)").
+class PendingEntryWrite {
+  const PendingEntryWrite({
+    required this.tempId,
+    required this.content,
+    required this.source,
+    required this.mediaDurationSeconds,
+    required this.startedAt,
+    required this.status,
+  });
+
+  final String tempId;
+  final String content;
+  final EntrySource source;
+
+  /// Carried through verbatim for a retry's own replayed `create()` call —
+  /// mirrors [Entry.mediaDurationSeconds]'s own "non-null only for audio"
+  /// contract.
+  final int? mediaDurationSeconds;
+
+  /// When this write first started — also doubles as the placeholder
+  /// card's own `occurredAt` while pending (`MeusRegistrosLoaded`'s own
+  /// placeholder-`Entry` construction), so a pending write always renders
+  /// at the top of "Hoje" until it resolves.
+  final DateTime startedAt;
+
+  final PendingEntryWriteStatus status;
+
+  PendingEntryWrite copyWith({PendingEntryWriteStatus? status}) =>
+      PendingEntryWrite(
+        tempId: tempId,
+        content: content,
+        source: source,
+        mediaDurationSeconds: mediaDurationSeconds,
+        startedAt: startedAt,
+        status: status ?? this.status,
+      );
+
+  @override
+  bool operator ==(Object other) =>
+      identical(this, other) ||
+      (other is PendingEntryWrite &&
+          other.tempId == tempId &&
+          other.content == content &&
+          other.source == source &&
+          other.mediaDurationSeconds == mediaDurationSeconds &&
+          other.startedAt == startedAt &&
+          other.status == status);
+
+  @override
+  int get hashCode => Object.hash(
+    tempId,
+    content,
+    source,
+    mediaDurationSeconds,
+    startedAt,
+    status,
+  );
+
+  @override
+  String toString() =>
+      'PendingEntryWrite(tempId: $tempId, content: $content, source: '
+      '$source, mediaDurationSeconds: $mediaDurationSeconds, startedAt: '
+      '$startedAt, status: $status)';
+}
diff --git a/lib/features/entries/domain/entities/sync_badge_state.dart b/lib/features/entries/domain/entities/sync_badge_state.dart
new file mode 100644
index 0000000..a6a8453
--- /dev/null
+++ b/lib/features/entries/domain/entities/sync_badge_state.dart
@@ -0,0 +1,102 @@
+import '../../../../core/failure/failure.dart';
+import 'entry.dart';
+import 'pending_entry_write.dart';
+
+/// A single `EntryRecordCard`'s own sync badge (AD-10) — exactly the 3
+/// states `docs/input/backend/sync-badge.md` names, never a 4th: the
+/// server exposes no sync field of its own, so these 3 are the complete
+/// set this app ever needs to render. Sealed, with `const factory`
+/// constructors on the base class (mirrors `Failure`'s own shape, minus
+/// the `freezed` codegen — no `==`/`copyWith` machinery is needed here
+/// beyond the hand-rolled equality each subclass already carries) so call
+/// sites read as `SyncBadgeState.synchronizing()` rather than naming each
+/// subclass directly.
+sealed class SyncBadgeState {
+  const SyncBadgeState();
+
+  const factory SyncBadgeState.synchronizing() = SyncBadgeSynchronizing;
+
+  const factory SyncBadgeState.synchronized() = SyncBadgeSynchronized;
+
+  const factory SyncBadgeState.error(Failure failure) = SyncBadgeError;
+}
+
+/// "Synchronizing" (ochre) — a local write not yet confirmed by the
+/// server.
+class SyncBadgeSynchronizing extends SyncBadgeState {
+  const SyncBadgeSynchronizing();
+
+  @override
+  bool operator ==(Object other) => other is SyncBadgeSynchronizing;
+
+  @override
+  int get hashCode => (SyncBadgeSynchronizing).hashCode;
+
+  @override
+  String toString() => 'SyncBadgeSynchronizing()';
+}
+
+/// "Synchronized" (green) — nothing pending for this entry; the last
+/// confirmed write matched.
+class SyncBadgeSynchronized extends SyncBadgeState {
+  const SyncBadgeSynchronized();
+
+  @override
+  bool operator ==(Object other) => other is SyncBadgeSynchronized;
+
+  @override
+  int get hashCode => (SyncBadgeSynchronized).hashCode;
+
+  @override
+  String toString() => 'SyncBadgeSynchronized()';
+}
+
+/// "Synchronization error" (red) — the write was attempted and failed,
+/// never yet reconciled. [failure] is kept so the badge's own tap handler
+/// (`SyncBadge`) can read [Failure.retryable]/[Failure.message] directly,
+/// per the Boundaries' "Tap on error badge" rule.
+class SyncBadgeError extends SyncBadgeState {
+  const SyncBadgeError(this.failure);
+
+  final Failure failure;
+
+  @override
+  bool operator ==(Object other) =>
+      identical(this, other) ||
+      (other is SyncBadgeError && other.failure == failure);
+
+  @override
+  int get hashCode => failure.hashCode;
+
+  @override
+  String toString() => 'SyncBadgeError(failure: $failure)';
+}
+
+/// The one place this app ever decides a card's badge (Never: "any screen
+/// recomputing badge state inline") — pure, no I/O, no `package:flutter`
+/// import (RNF06).
+///
+/// [pending] wins whenever it's non-null, regardless of [entry] — per
+/// `sync-badge.md`, "Synchronizing"/"Synchronization error" both describe
+/// *client-side pending state*, not anything read off [entry] itself, so a
+/// pending write's own status is always the authoritative answer for
+/// whichever card it belongs to. Once [pending] is `null`, the existence of
+/// a confirmed [entry] already means "it is on the server" (sync-
+/// badge.md: "it is on the server already means synchronized, by
+/// definition") -> [SyncBadgeSynchronized]. [entry] and [pending] both
+/// `null` is unreachable from every real caller (`MeusRegistrosLoaded`
+/// always derives a displayed card from one or the other, never neither)
+/// but still resolves to [SyncBadgeSynchronized] rather than throwing
+/// (RNF09-style defensiveness) — "nothing pending" is the closest true
+/// reading of that combination regardless of [entry].
+SyncBadgeState deriveSyncBadgeState(Entry? entry, PendingEntryWrite? pending) {
+  if (pending != null) {
+    return switch (pending.status) {
+      PendingEntryWriteInFlight() => const SyncBadgeState.synchronizing(),
+      PendingEntryWriteFailed(failure: final failure) => SyncBadgeState.error(
+        failure,
+      ),
+    };
+  }
+  return const SyncBadgeState.synchronized();
+}
diff --git a/lib/features/entries/domain/services/pending_entry_write_tracker.dart b/lib/features/entries/domain/services/pending_entry_write_tracker.dart
new file mode 100644
index 0000000..a9460ff
--- /dev/null
+++ b/lib/features/entries/domain/services/pending_entry_write_tracker.dart
@@ -0,0 +1,233 @@
+// The constructor keeps the public named param (`repository`) distinct
+// from the private field it initializes, matching `session_repository_
+// impl.dart`'s/`auth_repository_impl.dart`'s documented convention.
+// ignore_for_file: prefer_initializing_formals
+import 'dart:async';
+
+import 'package:fpdart/fpdart.dart';
+
+import '../../../../core/failure/failure.dart';
+import '../entities/entry.dart';
+import '../entities/pending_entry_write.dart';
+import '../repositories/entries_repository.dart';
+
+/// The single `create()`/`retry()` entry point for all three capture
+/// cubits (`TextEntryCubit`/`AudioEntryCubit`/`PhotoEntryCubit`) — Intent:
+/// "the tracker, not `MeusRegistrosCubit`, owns reconciliation". Pure
+/// Dart, no `package:flutter`/`data` import (RNF06) — a port+impl pair in
+/// one file, same structural convention `SessionExpiryNotifier`/
+/// `SessionExpiryNotifierImpl` already use.
+abstract class PendingEntryWriteTracker {
+  /// Identical contract to [EntriesRepository.create] (Boundaries) — every
+  /// capture cubit swaps its `EntriesRepository` dependency for this one,
+  /// with no other call-site change. Internally: records an optimistic
+  /// [PendingEntryWrite] (status [PendingEntryWriteInFlight]) *before*
+  /// calling through to the repository, so [pendingWrites] reflects it
+  /// immediately; on success, drops the record and emits the confirmed
+  /// [Entry] on [confirmedWrites]; on failure, flips the record to
+  /// [PendingEntryWriteFailed] and leaves it for [retry].
+  Future<Either<Failure, Entry>> create({
+    required String content,
+    required EntrySource source,
+    int? mediaDurationSeconds,
+  });
+
+  /// Replays the exact same payload a failed write ([tempId]) was created
+  /// with (Never: "a second retry endpoint — retry replays `create()`
+  /// verbatim"). A no-op for an unknown [tempId] or one that isn't
+  /// currently [PendingEntryWriteFailed] (e.g. already in flight, or
+  /// already resolved).
+  Future<void> retry(String tempId);
+
+  /// Releases the underlying stream resources — wired into `get_it`'s own
+  /// reset lifecycle (`entries_injection.dart`'s `dispose:`), same
+  /// convention `SessionExpiryNotifier.dispose()`/`SessionRepository.
+  /// dispose()` already use.
+  Future<void> dispose();
+
+  /// Every write this tracker currently holds (in flight or failed) —
+  /// `MeusRegistrosCubit` overlays this on its own confirmed list (Intent).
+  /// Replay-capable: a late subscriber sees the current snapshot
+  /// immediately rather than only future changes (`Stream.multi` + cached
+  /// last value, mirrors `SessionRepositoryImpl.statusStream`,
+  /// `session_repository_impl.dart:69-89`) — necessary here because
+  /// `MeusRegistrosCubit` is a long-lived singleton that may subscribe
+  /// well after a write is already pending (e.g. the user opens "Meus
+  /// Registros" after already starting a save from Home).
+  Stream<List<PendingEntryWrite>> get pendingWrites;
+
+  /// Broadcasts the real, server-confirmed [Entry] — paired with the
+  /// [PendingEntryWrite.tempId] it resolved from — the instant a
+  /// [create]/[retry] call resolves successfully. The one channel
+  /// `MeusRegistrosCubit` (which never calls [create]/[retry] itself, and
+  /// never talks to a capture cubit directly, AD-7) has to learn of a
+  /// just-confirmed write and prepend it into its own state (Boundaries:
+  /// "tracker drops the record; `MeusRegistrosCubit` prepends the
+  /// confirmed `Entry` into its own state"). No replay semantics, same
+  /// rationale `SessionExpiryNotifier.expiredEvents` already documents: a
+  /// one-shot signal per confirmation, not a value a late subscriber needs
+  /// to catch up on — a write that confirmed before `MeusRegistrosCubit`
+  /// ever subscribed will simply arrive through its next `list()`
+  /// instead.
+  ///
+  /// The paired `tempId` (Review finding) lets a listener drop its own
+  /// locally-held pending placeholder for this exact write in the very
+  /// same synchronous handler that prepends the confirmed [Entry] —
+  /// `pendingWrites`' own removal of the same record is a separate
+  /// `Stream.multi`-wrapped subscription that can otherwise deliver one
+  /// microtask late, which previously left a one-frame window where both
+  /// the stale placeholder and the real confirmed entry rendered at once.
+  Stream<({String tempId, Entry entry})> get confirmedWrites;
+}
+
+/// Default implementation — an in-memory `Map` of outstanding writes
+/// (Never: "persisting pending writes" — nothing here ever touches disk;
+/// a killed app loses every pending record, by design, UX-DR30).
+class PendingEntryWriteTrackerImpl implements PendingEntryWriteTracker {
+  PendingEntryWriteTrackerImpl({required EntriesRepository repository})
+    : _repository = repository;
+
+  final EntriesRepository _repository;
+
+  /// Insertion order matters for display (Boundaries: "Card appears
+  /// top-of-today... before server responds") — a `Map` preserves it in
+  /// Dart, and lookups by [PendingEntryWrite.tempId] (for [retry]) stay
+  /// O(1).
+  final Map<String, PendingEntryWrite> _pending = {};
+
+  final StreamController<List<PendingEntryWrite>> _pendingController =
+      StreamController<List<PendingEntryWrite>>.broadcast();
+
+  final StreamController<({String tempId, Entry entry})> _confirmedController =
+      StreamController<({String tempId, Entry entry})>.broadcast();
+
+  /// Monotonic suffix so two `create()` calls landing in the very same
+  /// microtask (e.g. two fast capture saves) never collide on
+  /// [DateTime.now]'s own millisecond resolution.
+  int _nextSuffix = 0;
+
+  List<PendingEntryWrite> get _snapshot => List.unmodifiable(_pending.values);
+
+  @override
+  Stream<List<PendingEntryWrite>> get pendingWrites {
+    // Mirrors `SessionRepositoryImpl.statusStream` exactly: a fresh
+    // listener gets the current snapshot synchronously, then every
+    // further change the shared broadcast controller delivers.
+    return Stream<List<PendingEntryWrite>>.multi((controller) {
+      controller.add(_snapshot);
+      final subscription = _pendingController.stream.listen(
+        controller.add,
+        onError: controller.addError,
+        onDone: controller.close,
+      );
+      controller.onCancel = subscription.cancel;
+    }, isBroadcast: true);
+  }
+
+  @override
+  Stream<({String tempId, Entry entry})> get confirmedWrites =>
+      _confirmedController.stream;
+
+  void _emitPending() {
+    if (_pendingController.isClosed) {
+      return;
+    }
+    _pendingController.add(_snapshot);
+  }
+
+  String _generateTempId() =>
+      'pending-${DateTime.now().microsecondsSinceEpoch}-${_nextSuffix++}';
+
+  @override
+  Future<Either<Failure, Entry>> create({
+    required String content,
+    required EntrySource source,
+    int? mediaDurationSeconds,
+  }) async {
+    // Spec amendment (code-review round 1): drops any existing `failed`
+    // record *before* registering the new `inFlight` one — exactly one
+    // Insertion Modal exists app-wide, so a user retrying by tapping
+    // "Salvar" again in the same still-open modal (not via the badge)
+    // must not leave the superseded attempt's error card as a permanent
+    // orphan on Meus Registros. Mutated in the same pass as the new
+    // record's own insertion below, so only one combined snapshot is ever
+    // emitted for this — never an intermediate "failed just removed, new
+    // one not yet added" one.
+    _pending.removeWhere(
+      (_, write) => write.status is PendingEntryWriteFailed,
+    );
+    final tempId = _generateTempId();
+    _pending[tempId] = PendingEntryWrite(
+      tempId: tempId,
+      content: content,
+      source: source,
+      mediaDurationSeconds: mediaDurationSeconds,
+      startedAt: DateTime.now(),
+      status: const PendingEntryWriteInFlight(),
+    );
+    _emitPending();
+
+    final result = await _repository.create(
+      content: content,
+      source: source,
+      mediaDurationSeconds: mediaDurationSeconds,
+    );
+    _resolve(tempId, result);
+    return result;
+  }
+
+  @override
+  Future<void> retry(String tempId) async {
+    final current = _pending[tempId];
+    if (current == null || current.status is! PendingEntryWriteFailed) {
+      // Unknown, already in flight, or already resolved — I/O matrix's
+      // "Write fails, non-retryable" row also routes through this guard
+      // indirectly: `SyncBadge` only ever calls [retry] for a
+      // `Failure.retryable` error in the first place, but this stays the
+      // authoritative check regardless of how `retry()` is invoked.
+      return;
+    }
+    _pending[tempId] = current.copyWith(status: const PendingEntryWriteInFlight());
+    _emitPending();
+
+    final result = await _repository.create(
+      content: current.content,
+      source: current.source,
+      mediaDurationSeconds: current.mediaDurationSeconds,
+    );
+    _resolve(tempId, result);
+  }
+
+  /// Shared success/failure handling for both [create] and [retry] — on
+  /// success, drops the pending record and broadcasts the confirmed
+  /// [Entry]; on failure, flips the record to [PendingEntryWriteFailed]
+  /// (re-reads [_pending] rather than trusting a closed-over reference, in
+  /// case a concurrent call already replaced it).
+  void _resolve(String tempId, Either<Failure, Entry> result) {
+    result.match(
+      (failure) {
+        final latest = _pending[tempId];
+        if (latest == null) {
+          return;
+        }
+        _pending[tempId] = latest.copyWith(
+          status: PendingEntryWriteFailed(failure: failure),
+        );
+        _emitPending();
+      },
+      (entry) {
+        _pending.remove(tempId);
+        _emitPending();
+        if (!_confirmedController.isClosed) {
+          _confirmedController.add((tempId: tempId, entry: entry));
+        }
+      },
+    );
+  }
+
+  @override
+  Future<void> dispose() async {
+    await _pendingController.close();
+    await _confirmedController.close();
+  }
+}
